require_once __DIR__.'/../../includes/auth.php';require_role(['admin','production_manager']);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){flash_set('error','Invalid allocation ID.');redirect('modules/fabric_allocations/index.php');}
$sql="SELECT fa.*,fl.lot_number,fl.fabric_type,fl.color,fl.received_quantity,fl.unit,fl.inspection_status,s.supplier_name,pb.batch_number,pb.status batch_status,bo.order_number,bo.style_number,b.buyer_name,u.full_name allocator_name,u.username allocator_username FROM fabric_allocations fa JOIN fabric_lots fl ON fl.fabric_lot_id=fa.fabric_lot_id JOIN suppliers s ON s.supplier_id=fl.supplier_id JOIN production_batches pb ON pb.batch_id=fa.batch_id JOIN buyer_orders bo ON bo.order_id=pb.order_id JOIN buyers b ON b.buyer_id=bo.buyer_id JOIN users u ON u.user_id=fa.allocated_by WHERE fa.fabric_allocation_id=? LIMIT 1";$stmt=$conn->prepare($sql);if(!$stmt){error_log($conn->error);flash_set('error','Allocation could not be loaded.');redirect('modules/fabric_allocations/index.php');}$stmt->bind_param('i',$id);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$r){flash_set('error','Allocation not found.');redirect('modules/fabric_allocations/index.php');}
$pageTitle='Fabric Allocation '.$r['lot_number'];$currentNav='fabric_allocations';include __DIR__.'/../../includes/header.php';include __DIR__.'/../../includes/sidebar.php';
